RESET_MODES = ('auto', 'wait')


def _make_env(env_name: str, wrappers: list, add_pixels: bool = False, **kwargs) -> gym.Env:
    if add_pixels:
        kwargs.setdefault('render_mode', 'rgb_array')
    env = make(env_name, **kwargs)
    for wrapper in wrappers:
        env = wrapper(env)
    return env

